const program = new Command("gooi").description("Gooi's own command: slices and tasks");

const sliceCommands = program.command("slice").description("Track gooi's slices; only one is open at a time");

sliceCommands
  .command("status")
  .description("Show the open slice and the done slices")
  .action(() => run(commands.slice.commands.status, {}));

sliceCommands
  .command("open")
  .description("Open the next slice. Only one slice can be open at a time.")
  .requiredOption("--title <title>", "Short name for the slice")
  .option("--detail <detail>", "What the slice covers")
  .requiredOption("--done <done>", "When it can be closed, in terms of real use")
  .action((options) => run(commands.slice.commands.open, { title: options.title, detail: options.detail, done: options.done }));

sliceCommands
  .command("close")
  .description("Close the open slice with what it was used for")
  .requiredOption("--used <used>", "What the slice was actually used for")
  .action((options) => run(commands.slice.commands.close, { used: options.used }));

const taskCommands = program.command("task").description("Track tasks as Markdown files in tasks/");

taskCommands
  .command("list")
  .description("List open and done tasks, and any files that can't be read")
  .action(() => run(commands.task.commands.list, {}));

